package io.github.wyze3306.jtb.block;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.Arrays;
import java.util.zip.GZIPInputStream;

/**
 * Loads the static block tables ({@link JavaBlockStates}, {@link BedrockBlockPalette}) from
 * {@code mappings/block/blocks.bin.gz}, generated by {@code tools/gen_world_mappings.py}.
 */
public final class BlockData {

    private static final String RESOURCE = "mappings/block/blocks.bin.gz";
    private static volatile boolean loaded;

    private BlockData() {
    }

    /** Loads the tables once; later calls return immediately. */
    public static synchronized void load() {
        if (loaded) {
            return;
        }
        try (InputStream raw = BlockData.class.getClassLoader().getResourceAsStream(RESOURCE)) {
            if (raw == null) {
                throw new IOException(RESOURCE + " missing from the jar");
            }
            byte[] data;
            try (GZIPInputStream gzip = new GZIPInputStream(raw, 1 << 16)) {
                data = gzip.readAllBytes();
            }
            BlockDataReader in = new BlockDataReader(data);
            byte[] magic = in.bytes(4);
            int version = in.u8();
            if (!Arrays.equals(magic, new byte[]{'J', 'T', 'B', 'B'}) || version != 1) {
                throw new IOException("Unsupported " + RESOURCE + " format");
            }
            JavaBlockStates.load(in);
            BedrockBlockPalette.load(in);
            CustomBlockAllocator.initCarriers();
        } catch (IOException e) {
            throw new UncheckedIOException("Cannot load the block tables", e);
        }
        loaded = true;
    }
}
